<?php
require_once dirname(__DIR__) . '/_common.php';$id=isset($_GET['id'])?(int)$_GET['id']:0;$stmt=$pdo->prepare('SELECT * FROM galeri_album WHERE id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){osis_set_flash('error','Album tidak ditemukan.');osis_redirect('admin/galeri/index.php');}$pageTitle='Edit album';$error='';$activities=$pdo->query('SELECT id,judul,tanggal FROM kegiatan ORDER BY tanggal DESC')->fetchAll();
if(osis_admin_is_post()){osis_verify_csrf();$judul=osis_post_string('judul',180);$deskripsi=osis_post_string('deskripsi',4000);$tanggal=osis_post_string('tanggal',10);$kegiatanId=(int)(isset($_POST['kegiatan_id'])?$_POST['kegiatan_id']:0);if($judul===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal)){$error='Judul dan tanggal album wajib diisi.';}else{try{$stmt=$pdo->prepare('UPDATE galeri_album SET judul=?,deskripsi=?,tanggal=?,kegiatan_id=? WHERE id=?');$stmt->execute([$judul,$deskripsi?:null,$tanggal,$kegiatanId?:null,$id]);osis_log_activity('Memperbarui album galeri: '.$judul);osis_set_flash('success','Album berhasil diperbarui.');osis_redirect('admin/galeri/index.php');}catch(PDOException $exception){$error=osis_admin_handle_error($exception);}}}
osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap"><a class="back-link" href="<?=osis_e(osis_url('admin/galeri/index.php'))?>">← Galeri</a><div class="admin-panel form-panel"><span class="eyebrow">PERBARUI ALBUM</span><h2>Edit album</h2><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" data-validate-form><?=osis_csrf_input()?><label for="judul">Nama album</label><input id="judul" name="judul" required maxlength="180" value="<?=osis_e(isset($_POST['judul'])?$_POST['judul']:$item['judul'])?>"><label for="deskripsi">Deskripsi</label><textarea id="deskripsi" name="deskripsi" rows="4"><?=osis_e(isset($_POST['deskripsi'])?$_POST['deskripsi']:$item['deskripsi'])?></textarea><div class="form-grid"><div><label for="tanggal">Tanggal album / kegiatan</label><input id="tanggal" name="tanggal" type="date" required value="<?=osis_e(isset($_POST['tanggal'])?$_POST['tanggal']:$item['tanggal'])?>"></div><div><label for="kegiatan_id">Tautkan kegiatan <span class="optional">(opsional)</span></label><select id="kegiatan_id" name="kegiatan_id"><option value="">Tidak terkait kegiatan tertentu</option><?php foreach($activities as $activity):?><option value="<?=(int)$activity['id']?>" <?=((int)(isset($_POST['kegiatan_id'])?$_POST['kegiatan_id']:$item['kegiatan_id'])===(int)$activity['id'])?'selected':''?>><?=osis_e($activity['judul'].' · '.osis_format_date($activity['tanggal']))?></option><?php endforeach;?></select></div></div><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/galeri/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Simpan perubahan <span>↗</span></button></div></form></div></div>
